            else:
                other_cards.append((card, encrypted_cards[i]))

        # Sort royal cards by value
        royal_cards.sort(key=lambda x: x[0].value)

        # Combine final deck
        shuffled = [x[1] for x in royal_cards] + [x[1] for x in other_cards]
        return shuffled[:5] + random.sample(shuffled[5:], len(shuffled)-5)

    def play_round(self):
        try:
            # Get encrypted deck
            encrypted_cards = self.get_encrypted_deck()

            # Arrange winning hand
            shuffled_cards = self.arrange_royal_flush(encrypted_cards)

            # Submit shuffled deck
            self.r.recvuntil(b"one card at a time")
            for card in shuffled_cards:
                self.r.sendlineafter(b">>", str(card).encode())
                time.sleep(0.05)

            # Check result
            result = self.r.recvuntil([b"You win", b"I win", b"It is a tie", b"HAHAHAHA"])
            if b"HAHAHAHA" in result:
                return "flag"
            if b"You win" in result:
                self.wins += 1
                log.success(f"Won round {self.wins}/10!")
                self.r.recvuntil(b"Round")
                return True
            else:
                self.wins = 0
                log.failure("Lost round")
                return False

        except EOFError:
            log.error("Connection closed")
            return False

    def extract_flag_from_output(self, output):
        # Try to find encrypted flag value
        try:
            # Extract number after "Here is your flag "
            match = re.search(b"Here is your flag ([0-9]+)", output)
            if match:
                enc_flag = int(match.group(1))
                flag = long_to_bytes(pow(enc_flag, self.d, self.n))
                if b'csawctf{' in flag:
                    return flag.decode()
        except:
            pass
        return None

    def get_flag(self):
        try:
            data = self.r.recvuntil(b"!!", timeout=5)
            log.debug(f"Raw flag data: {data}")
            flag = self.extract_flag_from_output(data)

            if not flag:
                # Try receiving more data
                more_data = self.r.recv(timeout=1)
                log.debug(f"Additional data: {more_data}")
                flag = self.extract_flag_from_output(more_data)

            if flag:
                return flag
            raise Exception("Could not find flag in output")
        except Exception as e:
            log.error(f"Flag error: {str(e)}")
            return None

    def play_game(self):
        try:
            self.connect()
            self.setup_rsa()

            while self.wins < 10:
                result = self.play_round()
                if result == "flag":
                    log.info("Got flag prompt!")
                    flag = self.get_flag()
                    if flag:
                        return flag
                elif not result:
                    self.r.close()
                    time.sleep(1)
                    self.connect()
                    self.setup_rsa()
                    continue

                if self.wins == 10:
                    time.sleep(0.5)  # Wait a bit for the server
                    flag = self.get_flag()
                    if flag:
                        return flag

        except Exception as e:
            log.error(f"Game error: {str(e)}")
            if self.r:
                self.r.close()
            return None
        finally:
            if self.r:
                self.r.close()

def main():
