                val = y >> 1
                val = val ^ self.state[(i+42)%64]
                if y & 1:
                    val = val ^ 37
                self.state[i] = val
            self.index = 0
        seed = self.state[self.index]
        self.index += 1
        return (seed*15 + 17)%(2**6)

def find_prng_seed(first_shuffle):
    # Try different seeds until we match the shuffle pattern
    for seed in range(64):
        rng = PRNG(seed)
        matches = True
        for i in range(5):  # Check first few numbers to verify
            if rng.getnum() != first_shuffle[i]:
                matches = False
                break
        if matches:
            return seed
    return None

