                    log.failure("Lost round")
                self.wins = 0
                return False

        except EOFError:
            log.error("Connection closed")
            return False

    def get_flag(self):
        while True:
            try:
                self.connect()
                self.setup_rsa()

                # Initialize PRNG tracking
