                    "Ten": 10, "Jack": 11, "Queen": 12, "King": 13, "Ace": 14}
            return ranks.get(rank, -1)
        except:
            return -1

    def arrange_straight_flush(self, cards):
        suit_groups = {}
        for enc_card in cards:
            card = self.decrypt_card(enc_card)
            if card:
                try:
                    rank = card.split(" of ")[0]
                    suit = card.split(" of ")[1]
                    rank_val = self.get_card_rank(card)
                    if suit not in suit_groups:
                        suit_groups[suit] = []
                    suit_groups[suit].append((rank_val, enc_card))
                except:
                    continue

        # Look for straight flush
        for suit, values in suit_groups.items():
            if len(values) < 5:
                continue
            values.sort()
            for i in range(len(values)-4):
                if all(values[j+1][0] - values[j][0] == 1 for j in range(i, i+4)):
                    straight_flush = [v[1] for v in values[i:i+5]]
                    return straight_flush + [c for c in cards if c not in straight_flush]

        # Fall back to high cards
        return sorted(cards, key=lambda x: self.get_card_rank(self.decrypt_card(x) or ""), reverse=True)

    def play_hand(self):
        try:
            # Get and arrange deck
            self.conn.recvuntil(b"deck -->")
            deck = eval(self.conn.recvline().decode())
            arranged = self.arrange_straight_flush(deck)

            # Submit arranged cards
            self.conn.recvuntil(b"time")
            for card in arranged:
                self.conn.sendlineafter(b">>", str(card).encode())

            # Check result
            result = self.conn.recvuntil([b"You win!", b"I win!", b"It is a tie!", b"Congratulations!", b"encrypted flag"])

            if b"encrypted flag" in result:
                enc_flag = int(self.conn.recvline().decode().strip())
                flag = long_to_bytes(pow(enc_flag, self.d, self.n))
                return flag.decode()

            if b"You win!" in result:
                self.wins += 1
                print(f"Won round {self.wins}/10!")
                if self.wins < 10:
                    self.conn.recvuntil(b"Round")
                return True

            if b"I win!" in result or b"tie" in result:
                self.wins = 0
                print("Lost round or tie")
                return False

        except EOFError:
            print("Connection closed unexpectedly")
            return False
        except Exception as e:
            print(f"Error in play_hand: {str(e)}")
            return False

    def solve(self):
        while True:
            try:
                self.connect()
                if not self.init_rsa():
                    continue

                # Play rounds until we win
                while self.wins < 10:
                    result = self.play_hand()

                    if isinstance(result, str) and "csawctf{" in result:
                        print(f"Found flag: {result}")
                        return result

                    if not result:
                        break

                    time.sleep(0.1)

            except Exception as e:
                print(f"Error in solve: {str(e)}")

            finally:
                if self.conn:
                    self.conn.close()

            time.sleep(1)

def main():
    game = PokerGame()
    flag = game.solve()
    if flag:
        print(f"Final flag: {flag}")
        with open("flag.txt", "w") as f:
            f.write(flag)
        return True
    return False

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from pwn import *
from Crypto.Util.number import long_to_bytes, bytes_to_long
import re
import time

# Configure logging
context.log_level = 'error'
host = 'crypto.chal.csaw.io'
port = 5000

class PRNG:
    def __init__(self, seed):
        self.seed = seed % 64
        self.state = [self.seed]
        self.index = 64
        for i in range(63):
            self.state.append((3 * (self.state[i] ^ (self.state[i-1] >> 4)) + i+1) % 64)

    def getnum(self):
        if self.index >= 64:
            for i in range(64):
                y = (self.state[i] & 0x20) + (self.state[(i+1)%64] & 0x1f)
                val = y >> 1
                val = val ^ self.state[(i+42)%64]
                if y & 1:
                    val = val ^ 37
                self.state[i] = val
            self.index = 0
        seed = self.state[self.index]
        self.index += 1
        return (seed*15 + 17) % (2**6)

def find_prng_seed(nums):
    nums = [x % 64 for x in nums]
    for seed in range(64):
        rng = PRNG(seed)
        valid = True
        for n in nums:
            if rng.getnum() != n:
                valid = False
                break
        if valid:
            return seed
    return None

class Poker:
    def __init__(self):
        self.conn = None
        self.p = None
        self.q = None
        self.n = None
        self.e = 65537
        self.d = None
        self.rng = None
        self.wins = 0
        self.VALUES = {
            'Zero': 0, 'One': 1, 'Two': 2, 'Three': 3, 'Four': 4,
            'Five': 5, 'Six': 6, 'Seven': 7, 'Eight': 8, 'Nine': 9,
            'Ten': 10, 'Jack': 11, 'Queen': 12, 'King': 13, 'Ace': 14
        }

    def connect(self):
        self.conn = remote(host, port, timeout=30)

    def setup_rsa(self):
        data = self.conn.recvuntil(b"public exponent?").decode()
        primes = re.findall(r'primes.*?--> (\d+), (\d+)', data)[0]
        self.p, self.q = map(int, primes)
        self.n = self.p * self.q
        phi = (self.p - 1) * (self.q - 1)
        self.d = pow(self.e, -1, phi)

        # Send our RSA parameters
        self.conn.sendline(str(self.e).encode())
        self.conn.sendlineafter(b"private exponent?", str(self.d).encode())

    def decrypt_card(self, enc):
        try:
            dec = pow(int(enc), self.d, self.n)
            return long_to_bytes(dec).decode()
        except:
            return None

    def parse_card(self, card_str):
        if not card_str:
            return (-1, '')
        try:
            rank, suit = card_str.split(' of ')
            return (self.VALUES.get(rank, -1), suit)
        except:
            return (-1, '')

    def arrange_winning_hand(self, deck):
        cards = []
        for enc in deck:
            card = self.decrypt_card(enc)
            if card:
                rank, suit = self.parse_card(card)
                if rank >= 0:
                    cards.append((rank, suit, enc))

        # Sort by rank first, then group by suit for flush possibilities
        cards.sort(key=lambda x: (-x[0], x[1]))

        # Group by suit
        suit_groups = {}
        for card in cards:
            suit = card[1]
            if suit not in suit_groups:
                suit_groups[suit] = []
            suit_groups[suit].append(card)

        # Look for straight flush
        for suit, suited_cards in suit_groups.items():
            if len(suited_cards) >= 5:
                suited_cards.sort(key=lambda x: -x[0])
                for i in range(len(suited_cards)-4):
                    if all(suited_cards[j][0] - suited_cards[j+1][0] == 1 for j in range(i, i+4)):
                        winning = suited_cards[i:i+5]
                        rest = [c for c in cards if (c[0], c[1]) not in [(w[0], w[1]) for w in winning]]
                        return [w[2] for w in winning] + [r[2] for r in rest]

        # No straight flush, try for straight
        cards.sort(key=lambda x: -x[0])
        for i in range(len(cards)-4):
            if all(cards[j][0] - cards[j+1][0] == 1 for j in range(i, i+4)):
                winning = cards[i:i+5]
                rest = [c for c in cards if c not in winning]
                return [w[2] for w in winning] + [r[2] for r in rest]

        # Fallback to high cards
        return [c[2] for c in cards]

    def play_hand(self):
        try:
            # Get deck
            self.conn.recvuntil(b"deck -->")
            deck = eval(self.conn.recvline().decode())

            # Arrange cards for best hand
            arranged = self.arrange_winning_hand(deck)

            # Submit arranged cards
            self.conn.recvuntil(b"time")
            for card in arranged:
                self.conn.sendlineafter(b">>", str(card).encode())

            # Check result
            result = self.conn.recvuntil([b"You win!", b"I win!", b"It is a tie!",
                                        b"Congratulations!", b"encrypted flag"])

            if b"encrypted flag" in result:
                result = self.conn.recvline().decode()
                enc_flag = int(re.search(r"encrypted flag.*?(\d+)", result).group(1))
                flag = long_to_bytes(pow(enc_flag, self.d, self.n))
                return flag.decode()

            if b"You win!" in result:
                self.wins += 1
                if self.wins < 10:
                    self.conn.recvuntil(b"Round")
                return True

            self.wins = 0
            return False

        except EOFError:
            return False
        except Exception as e:
            print(f"Error in play_hand: {str(e)}")
            return False

    def play_game(self):
        try:
            self.connect()
            self.setup_rsa()

            while self.wins < 10:
                result = self.play_hand()

                if isinstance(result, str) and "csawctf{" in result:
                    return result

                if not result:
                    return None

                time.sleep(0.1)

        except Exception as e:
            print(f"Error in play_game: {str(e)}")

        finally:
            if self.conn:
                self.conn.close()

def solve_challenge():
    while True:
        try:
            poker = Poker()
