if __name__ == "__main__":
    solve_challenge()

#!/usr/bin/env python3
from pwn import *
import gmpy2
from Crypto.Util.number import long_to_bytes, bytes_to_long
import re
import time

# Optimize logging and connection settings
context.log_level = 'critical'
host = 'crypto.chal.csaw.io'
port = 5000

class RSAHelper:
    def __init__(self, p, q):
        self.p = p
        self.q = q
        self.n = p * q
        self.e = 65537
        self.d = pow(self.e, -1, (p-1)*(q-1))

    def decrypt(self, ct):
        try:
            pt = pow(int(ct), self.d, self.n)
            return long_to_bytes(pt).decode()
        except:
            return None

class CardManager:
    VALUES = {
        'Zero': 0, 'One': 1, 'Two': 2, 'Three': 3, 'Four': 4,
        'Five': 5, 'Six': 6, 'Seven': 7, 'Eight': 8, 'Nine': 9,
        'Ten': 10, 'Jack': 11, 'Queen': 12, 'King': 13, 'Ace': 14
    }

    @staticmethod
    def parse_card(card_str):
        if not card_str:
            return None
        try:
            rank, suit = card_str.split(' of ')
            return (CardManager.VALUES.get(rank, -1), suit)
        except:
            return None

    @staticmethod
    def arrange_winning_hand(cards):
        # Group by suit
        suits = {}
        for rank, suit, enc in cards:
            if suit not in suits:
                suits[suit] = []
            suits[suit].append((rank, enc))

        # Look for straight flush
        for suited_cards in suits.values():
            if len(suited_cards) >= 5:
                suited_cards.sort(key=lambda x: -x[0])
                for i in range(len(suited_cards)-4):
                    if all(suited_cards[j][0] - suited_cards[j+1][0] == 1 for j in range(i, i+4)):
                        winning = suited_cards[i:i+5]
                        rest = [c for c in cards if c[2] not in [w[1] for w in winning]]
                        return [w[1] for w in winning] + [r[2] for r in rest]

        # High cards
        cards.sort(key=lambda x: -x[0])
        return [c[2] for c in cards]

class PokerGame:
    def __init__(self):
        self.conn = None
        self.rsa = None
        self.wins = 0

    def connect(self):
        self.conn = remote(host, port, timeout=15)

    def init_game(self):
        data = self.conn.recvuntil(b"public exponent?").decode()
        p, q = map(int, re.findall(r"primes.*?--> (\d+), (\d+)", data)[0])
        self.rsa = RSAHelper(p, q)

        self.conn.sendline(str(self.rsa.e).encode())
        self.conn.sendlineafter(b"private exponent?", str(self.rsa.d).encode())

    def play_round(self):
        try:
            # Get encrypted deck
            self.conn.recvuntil(b"deck -->")
            deck = eval(self.conn.recvline().decode())

            # Decrypt and parse cards
            cards = []
            for enc in deck:
                card = self.rsa.decrypt(enc)
                if card:
                    parsed = CardManager.parse_card(card)
                    if parsed:
                        rank, suit = parsed
                        cards.append((rank, suit, enc))

            # Arrange cards for best hand
            arranged = CardManager.arrange_winning_hand(cards)

            # Submit arranged deck
            self.conn.recvuntil(b"time")
            for card in arranged:
                self.conn.sendlineafter(b">>", str(card).encode())

            # Check result
            result = self.conn.recvuntil([b"You win!", b"I win!", b"It is a tie!",
                                        b"Congratulations!", b"encrypted flag"])

            if b"encrypted flag" in result:
                enc_flag = int(self.conn.recvline().decode().strip())
                flag = long_to_bytes(pow(enc_flag, self.rsa.d, self.rsa.n))
                return flag.decode()

            if b"You win!" in result:
                self.wins += 1
                print(f"Won round {self.wins}/10")
                if self.wins < 10:
                    self.conn.recvuntil(b"Round")
                return True

            self.wins = 0
            print("Lost round")
            return False

        except EOFError:
            return False
        except Exception as e:
            print(f"Error in round: {str(e)}")
            return False

    def play(self):
        try:
            self.connect()
            self.init_game()

            while self.wins < 10:
                result = self.play_round()

                if isinstance(result, str) and "csawctf{" in result:
                    return result

                if not result:
                    break

                time.sleep(0.1)

        except Exception as e:
            print(f"Error in game: {str(e)}")

        finally:
            if self.conn:
                self.conn.close()

        return None

def solve():
    while True:
